/** Caller-owned key material for local TDS1 decoding. No keys are included in the SDK. */
export interface SaveDecryptionKeys {
  /** AES-256 key: 32 bytes, supplied as a Uint8Array or canonical base64. */
  encryption: Uint8Array | string
  /** HMAC-SHA-256 key: 32 bytes, supplied as a Uint8Array or canonical base64. */
  authentication: Uint8Array | string
  /** Byte-mask key: 32 bytes, supplied as a Uint8Array or canonical base64. */
  mask: Uint8Array | string
}

/** Encrypted saves require keys; unencrypted files need no options. */
export interface SaveDecodeOptions {
  keys?: SaveDecryptionKeys
}
